#!/bin/sh
set -eu
er=$("$EV" --session S1 --type external-review.received --root self --body '{"pr":"pr-1","head":"h1","threads":[{"thread":"t1","file":"a.sh","text":"quote this variable"},{"thread":"t2","file":null,"text":"add a usage line"}]}')
gr=$("$EV" --session S1 --type gate.answered --root "$er" --body '{"step":"review","answer":"yes, judge the review"}')
r1=$("$EV" --session S1 --type round.made --root "$er" --body '{"kind":"external","targets":['"$er"'],"base":null,"head":"h1","slots":[{"slot":1,"kind":"shell","agent_type":"lab-reviewer","cover":["t1","t2"]}],"loop":null}')
v1=$("$EV" --session S1 --type job.dispatched --root "$er" --round "$r1" --body '{"kind":"external-review","target":'"$r1"',"tree":"repo","report":"reports/4.json","agent_type":"lab-reviewer","delivery":"cold","hot_agent":null,"slot":1,"replaces":null,"approval":'"$gr"',"payload":{"threads":["t1","t2"]},"act":{}}')
"$EV" --session S1 --type job.assigned --root "$er" --round "$r1" --job "$v1" --agent ar1 --body '{"name":"review-shell-ar1","tool_use_id":"tu-v1"}' >/dev/null
"$EV" --session S1 --type review.submitted --root "$er" --round "$r1" --job "$v1" --agent ar1 --body '{"report":"reports/'"$v1"'.json","findings":[{"kind":"shell","file":"a.sh","severity":"medium","realism":"realistic","title":"unquoted variable","thread":"t1"},{"kind":"shell","file":"a.sh","severity":"low","realism":"realistic","title":"usage line missing","thread":"t2"}],"threads":{"t1":"valid","t2":"rejected"}}' >/dev/null
m1=$("$EV" --session S1 --type review.merged --root "$er" --round "$r1" --body '{"findings":[{"id":"SHELL-01","kind":"shell","file":"a.sh","severity":"medium","realism":"realistic","status":"open"},{"id":"SHELL-02","kind":"shell","file":"a.sh","severity":"low","realism":"realistic","status":"open"}],"verdict":"changes","targets":["SHELL-01"],"gaps":[]}')
fc=$("$EV" --session S1 --type fix.chosen --root "$er" --body '{"merge":'"$m1"',"query":{"severities":["medium"]},"ids":["SHELL-01"],"cap":2}')
fj=$("$EV" --session S1 --type job.dispatched --root "$er" --body '{"kind":"fix","target":'"$m1"',"tree":"repo","report":"reports/9.json","agent_type":"lab-builder","delivery":"cold","hot_agent":null,"slot":null,"replaces":null,"approval":'"$fc"',"payload":{"findings":[{"id":"SHELL-01","kind":"shell","file":"a.sh","severity":"medium","title":"unquoted variable"}],"side":"production"},"act":{}}')
"$EV" --session S1 --type job.assigned --root "$er" --job "$fj" --agent ab1 --body '{"name":"build-ab1","tool_use_id":"tu-f1"}' >/dev/null
fs=$("$EV" --session S1 --type build.submitted --root "$er" --job "$fj" --agent ab1 --body '{"commit":"c2","files":["a.sh"],"report":"reports/'"$fj"'.json","answers":{"SHELL-01":"done"},"declines":{}}')
r2=$("$EV" --session S1 --type round.made --root "$er" --body '{"kind":"code","targets":['"$fs"'],"base":"h1","head":"c2","slots":[{"slot":1,"kind":"shell","agent_type":"lab-reviewer","cover":["a.sh"]}],"loop":'"$fc"'}')
v2=$("$EV" --session S1 --type job.dispatched --root "$er" --round "$r2" --body '{"kind":"review","target":'"$r2"',"tree":"repo","report":"reports/13.json","agent_type":"lab-reviewer","delivery":"hot","hot_agent":"ar1","slot":1,"replaces":null,"approval":'"$fc"',"payload":{"cover":["a.sh"],"diff":"h1..c2","earlier":[{"id":"SHELL-01","status":"open","title":"unquoted variable","answer":"done","decline":null}],"skipped":["SHELL-02"]},"act":{}}')
"$EV" --session S1 --type job.assigned --root "$er" --round "$r2" --job "$v2" --agent ar1 --body '{"name":"review-shell-ar1","tool_use_id":"tu-v2"}' >/dev/null
"$EV" --session S1 --type review.submitted --root "$er" --round "$r2" --job "$v2" --agent ar1 --body '{"report":"reports/'"$v2"'.json","findings":[],"answers":{"SHELL-01":"fixed"}}' >/dev/null
"$EV" --session S1 --type review.merged --root "$er" --round "$r2" --body '{"findings":[{"id":"SHELL-01","kind":"shell","file":"a.sh","severity":"medium","realism":"realistic","status":"fixed"},{"id":"SHELL-02","kind":"shell","file":"a.sh","severity":"low","realism":"realistic","status":"skipped"}],"verdict":"pass","targets":[],"gaps":[]}' >/dev/null
"$EV" --session S1 --type loop.ended --root "$er" --body '{"reason":"clean"}' >/dev/null
